mapper.insert:
INSERT INTO fin_ex_chat_event_t(
    id, tenant_id, user_id, session_id, run_id, seq, event_type, payload_json, created_at
)
SELECT #{id}, s.tenant_id, s.user_id, s.id, r.id, #{seq}, #{eventType}, #{payloadJson}, #{createdAt}
FROM fin_ex_chat_session_t s
JOIN fin_ex_chat_run_t r
  ON r.id = #{runId}
 AND r.session_id = s.id
 AND r.tenant_id = s.tenant_id
 AND r.user_id = s.user_id
WHERE s.id = #{sessionId}

INSERT INTO fin_ex_chat_event_t(
    id, tenant_id, user_id, session_id, run_id, seq, event_type, payload_json, created_at
)
SELECT #{id}, s.tenant_id, s.user_id, s.id, r.id, #{seq}, #{eventType}, #{payloadJson}, #{createdAt}
FROM fin_ex_chat_session_t s
JOIN fin_ex_chat_run_t r
  ON r.id = #{runId}
 AND r.session_id = s.id
 AND r.tenant_id = s.tenant_id
 AND r.user_id = s.user_id
 AND r.status = 'RUNNING'
JOIN fin_ex_chat_run_execution_t e
  ON e.run_id = r.id
 AND e.tenant_id = r.tenant_id
 AND e.user_id = r.user_id
 AND e.session_id = r.session_id
 AND e.owner_instance_id = #{ownerInstanceId}
 AND e.fencing_token = #{fencingToken}
 AND e.execution_status = 'RUNNING'
WHERE s.id = #{sessionId}

INSERT INTO fin_ex_chat_event_t( id, tenant_id, user_id, session_id, run_id, seq, event_type, payload_json, created_at ) SELECT v.id, s.tenant_id, s.user_id, s.id, r.id, v.seq, v.event_type, v.payload_json, v.created_at FROM ( VALUES
(#{row.id}, #{row.sessionId}, #{row.runId}, #{row.seq}, #{row.eventType}, #{row.payloadJson}, CAST(#{row.createdAt, javaType=java.time.Instant, jdbcType=TIMESTAMP} AS TIMESTAMPTZ))
) AS v(id, session_id, run_id, seq, event_type, payload_json, created_at) JOIN fin_ex_chat_session_t s ON s.id = v.session_id JOIN fin_ex_chat_run_t r ON r.id = v.run_id AND r.session_id = s.id AND r.tenant_id = s.tenant_id AND r.user_id = s.user_id AND r.status = 'RUNNING' JOIN fin_ex_chat_run_execution_t e ON e.run_id = r.id AND e.tenant_id = r.tenant_id AND e.user_id = r.user_id AND e.session_id = r.session_id AND e.owner_instance_id = #{ownerInstanceId} AND e.fencing_token = #{fencingToken} AND e.execution_status = 'RUNNING'

