SELECT 
FROM fin_ex_chat_event_t
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND session_id = #{sessionId}
  AND seq > #{afterSeq}
ORDER BY seq ASC

SELECT 
FROM fin_ex_chat_event_t
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND session_id = #{sessionId}
  AND run_id = #{runId}
  AND seq > #{afterSeq}
ORDER BY seq ASC

SELECT COALESCE(MAX(seq), 0)
FROM fin_ex_chat_event_t
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND session_id = #{sessionId}
